+import { describe, it, expect } from 'vitest';
+import { computeBoundBoxForAnchor } from '@/utils/canvas/frame-bound-box';
+
+const MIN = 50;
+
+const oldBox = { x: 100, y: 200, width: 300, height: 400, rotation: 0 };
+
+describe('computeBoundBoxForAnchor', () => {
+  // --- Side anchors: horizontal locking ---
+  describe('middle-left anchor', () => {
+    it('locks y and height, allows width and x to change', () => {
+      const newBox = { x: 80, y: 210, width: 320, height: 450, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'middle-left', MIN);
+      expect(result).toEqual({ x: 80, y: oldBox.y, width: 320, height: oldBox.height, rotation: 0 });
+    });
+
+    it('returns oldBox when newBox.width is below minSize', () => {
+      const newBox = { x: 350, y: 200, width: 30, height: 400, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'middle-left', MIN);
+      expect(result).toEqual(oldBox);
+    });
+  });
+
+  describe('middle-right anchor', () => {
+    it('locks y and height, allows width change', () => {
+      const newBox = { x: 100, y: 210, width: 350, height: 450, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'middle-right', MIN);
+      expect(result).toEqual({ x: 100, y: oldBox.y, width: 350, height: oldBox.height, rotation: 0 });
+    });
+
+    it('returns oldBox when newBox.width is below minSize', () => {
+      const newBox = { x: 100, y: 200, width: 40, height: 400, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'middle-right', MIN);
+      expect(result).toEqual(oldBox);
+    });
+  });
+
+  // --- Side anchors: vertical locking ---
+  describe('top-center anchor', () => {
+    it('locks x and width, allows height and y to change', () => {
+      const newBox = { x: 110, y: 180, width: 320, height: 420, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'top-center', MIN);
+      expect(result).toEqual({ x: oldBox.x, y: 180, width: oldBox.width, height: 420, rotation: 0 });
+    });
+
+    it('returns oldBox when newBox.height is below minSize', () => {
+      const newBox = { x: 100, y: 560, width: 300, height: 30, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'top-center', MIN);
+      expect(result).toEqual(oldBox);
+    });
+  });
+
+  describe('bottom-center anchor', () => {
+    it('locks x and width, allows height change', () => {
+      const newBox = { x: 110, y: 200, width: 320, height: 380, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'bottom-center', MIN);
+      expect(result).toEqual({ x: oldBox.x, y: 200, width: oldBox.width, height: 380, rotation: 0 });
+    });
+
+    it('returns oldBox when newBox.height is below minSize', () => {
+      const newBox = { x: 100, y: 200, width: 300, height: 20, rotation: 0 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'bottom-center', MIN);
+      expect(result).toEqual(oldBox);
+    });
+  });
+
+  // --- Corner anchors: no locking ---
+  describe('corner anchors', () => {
+    it('top-left passes newBox through unchanged', () => {
+      const newBox = { x: 90, y: 190, width: 310, height: 410, rotation: 0 };
+      expect(computeBoundBoxForAnchor(oldBox, newBox, 'top-left', MIN)).toEqual(newBox);
+    });
+
+    it('top-right passes newBox through unchanged', () => {
+      const newBox = { x: 100, y: 190, width: 320, height: 410, rotation: 0 };
+      expect(computeBoundBoxForAnchor(oldBox, newBox, 'top-right', MIN)).toEqual(newBox);
+    });
+
+    it('bottom-left passes newBox through unchanged', () => {
+      const newBox = { x: 90, y: 200, width: 310, height: 420, rotation: 0 };
+      expect(computeBoundBoxForAnchor(oldBox, newBox, 'bottom-left', MIN)).toEqual(newBox);
+    });
+
+    it('bottom-right passes newBox through unchanged', () => {
+      const newBox = { x: 100, y: 200, width: 320, height: 420, rotation: 0 };
+      expect(computeBoundBoxForAnchor(oldBox, newBox, 'bottom-right', MIN)).toEqual(newBox);
+    });
+  });
+
+  // --- Edge cases ---
+  describe('edge cases', () => {
+    it('undefined anchor returns newBox', () => {
+      const newBox = { x: 110, y: 210, width: 280, height: 390, rotation: 0 };
+      expect(computeBoundBoxForAnchor(oldBox, newBox, undefined, MIN)).toEqual(newBox);
+    });
+
+    it('rotation is preserved from newBox', () => {
+      const newBox = { x: 100, y: 200, width: 300, height: 400, rotation: 45 };
+      const result = computeBoundBoxForAnchor(oldBox, newBox, 'top-left', MIN);
+      expect(result.rotation).toBe(45);
+    });
+  });
+});
