index 0000000..c78ec35
--- /dev/null
+++ b/tests/unit/components/canvas/frame-child-drag-clip.test.ts
@@ -0,0 +1,129 @@
+/**
+ * Tests for imperative clip management during child drag in FrameNode.
+ *
+ * Validates the fix for: "Frame children clipped on first drag after resize auto-group"
+ *
+ * Root cause: handleChildDragStart sets isDraggingChild via async React state,
+ * but Konva renders the next frame before React re-renders. After a resize,
+ * onTransformEnd leaves imperative clip attrs on the node, so React-Konva's
+ * prop diffing doesn't clear them. The fix adds synchronous imperative
+ * setAttrs calls alongside the React state updates.
+ *
+ * Key Konva detail: clipWidth/clipHeight use `typeof val === 'number'` check.
+ * Setting to 0 still clips (zero-size rect = invisible). Must use undefined.
+ */
+import { describe, it, expect } from 'vitest';
+
+// ---------------------------------------------------------------------------
+// Helpers: simulate the imperative clip logic extracted from FrameNode
+// ---------------------------------------------------------------------------
+
+/**
+ * Mirrors the clip-disable logic in handleChildDragStart.
+ * Returns the attrs object that would be passed to setAttrs().
+ */
+function computeClipDisableAttrs(shouldClip: boolean, clipGroupExists: boolean) {
+  if (!shouldClip || !clipGroupExists) return null;
+  return {
+    clipX: undefined,
+    clipY: undefined,
+    clipWidth: undefined,
+    clipHeight: undefined,
+  };
+}
+
+/**
+ * Mirrors the clip-restore logic in createChildDragEnd.
+ * Returns the attrs object that would be passed to setAttrs().
+ */
+function computeClipRestoreAttrs(
+  shouldClip: boolean,
+  clipGroupExists: boolean,
+  frameWidth: number,
+  frameHeight: number
+) {
+  if (!shouldClip || !clipGroupExists) return null;
+  return {
+    clipX: 0,
+    clipY: 0,
+    clipWidth: frameWidth,
+    clipHeight: frameHeight,
+  };
+}
+
+/**
+ * Simulates Konva's internal clipping check from Container.js:208
+ * `if (typeof clipWidth === 'number') { ... apply clip ... }`
+ */
+function konvaWouldClip(attrs: Record<string, unknown>): boolean {
+  return typeof attrs.clipWidth === 'number';
+}
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+
+describe('frame child drag clip management', () => {
+  describe('clip disable (drag start)', () => {
+    it('uses undefined (not 0) to disable clip — Konva checks typeof === number', () => {
+      const attrs = computeClipDisableAttrs(true, true);
+      expect(attrs).not.toBeNull();
+      expect(attrs!.clipX).toBeUndefined();
+      expect(attrs!.clipY).toBeUndefined();
+      expect(attrs!.clipWidth).toBeUndefined();
+      expect(attrs!.clipHeight).toBeUndefined();
+    });
+
+    it('disabled attrs should NOT trigger Konva clipping', () => {
+      const attrs = computeClipDisableAttrs(true, true)!;
+      expect(konvaWouldClip(attrs)).toBe(false);
+    });
+
+    it('returns null when shouldClip is false', () => {
+      expect(computeClipDisableAttrs(false, true)).toBeNull();
+    });
+
+    it('returns null when clipGroup does not exist', () => {
+      expect(computeClipDisableAttrs(true, false)).toBeNull();
+    });
+  });
+
+  describe('clip restore (drag end)', () => {
+    it('restores clip to (0, 0, frameWidth, frameHeight)', () => {
+      const attrs = computeClipRestoreAttrs(true, true, 400, 300);
+      expect(attrs).toEqual({
+        clipX: 0,
+        clipY: 0,
+        clipWidth: 400,
+        clipHeight: 300,
+      });
+    });
+
+    it('restored attrs should trigger Konva clipping', () => {
+      const attrs = computeClipRestoreAttrs(true, true, 400, 300)!;
+      expect(konvaWouldClip(attrs)).toBe(true);
+    });
+
+    it('returns null when shouldClip is false', () => {
+      expect(computeClipRestoreAttrs(false, true, 400, 300)).toBeNull();
+    });
+
+    it('returns null when clipGroup does not exist', () => {
+      expect(computeClipRestoreAttrs(true, false, 400, 300)).toBeNull();
+    });
+  });
+
+  describe('Konva typeof clipping semantics', () => {
+    it('clipWidth: 0 IS treated as clipping (zero-size = invisible)', () => {
+      expect(konvaWouldClip({ clipWidth: 0 })).toBe(true);
+    });
+
+    it('clipWidth: undefined disables clipping', () => {
+      expect(konvaWouldClip({ clipWidth: undefined })).toBe(false);
+    });
+
+    it('clipWidth: null disables clipping', () => {
+      expect(konvaWouldClip({ clipWidth: null })).toBe(false);
+    });
+  });
+});
