diff --git a/tests/unit/hooks/frame-creation-auto-group.test.ts b/tests/unit/hooks/frame-creation-auto-group.test.ts
new file mode 100644
index 0000000..81cc74b
--- /dev/null
+++ b/tests/unit/hooks/frame-creation-auto-group.test.ts
@@ -0,0 +1,502 @@
+import { describe, it, expect } from 'vitest';
+
+import type { CanvasObject, FrameObject, ImageObject, Panel } from '@/components/canvas/types';
+import {
+  findAutoGroupCandidates,
+  applyAutoGroup,
+  type AutoGroupCandidate,
+} from '@/utils/canvas/frame-auto-group';
+
+/**
+ * Tests for frame-creation auto-group candidate detection.
+ *
+ * During frame CREATION (mousemove while drawing), the hook constructs a
+ * synthetic FrameObject from the current draw bounds and calls
+ * findAutoGroupCandidates() to find objects that would be grouped when the
+ * user releases the mouse.
+ *
+ * These tests verify the utility behaves correctly for creation-specific
+ * scenarios (normalized bounds, shrinking rect, empty area, etc.).
+ */
+
+// ---------------------------------------------------------------------------
+// Fixture helpers (match patterns from frame-auto-group.test.ts)
+// ---------------------------------------------------------------------------
+
+const makeSyntheticFrame = (
+  x: number,
+  y: number,
+  width: number,
+  height: number
+): FrameObject => ({
+  id: 'synthetic-frame-preview',
+  type: 'frame',
+  position: { x, y },
+  width,
+  height,
+  scaleX: 1,
+  scaleY: 1,
+  rotation: 0,
+  children: [],
+  name: 'Frame Preview',
+  aspectRatio: undefined,
+});
+
+const makeImage = (
+  id: string,
+  x: number,
+  y: number,
+  size = 50
+): ImageObject => ({
+  id,
+  type: 'image',
+  position: { x, y },
+  width: size,
+  height: size,
+  scaleX: 1,
+  scaleY: 1,
+  rotation: 0,
+  src: `${id}.png`,
+});
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+
+describe('frame-creation-auto-group', () => {
+  it('should detect candidates when objects are inside frame creation bounds', () => {
+    // Synthetic frame as if being drawn: covers (0,0)→(300,300)
+    const syntheticFrame = makeSyntheticFrame(0, 0, 300, 300);
+
+    // img-1 at (50,50), 50x50 → center (75,75) — inside
+    const img1 = makeImage('img-1', 50, 50);
+    // img-2 at (150,150), 50x50 → center (175,175) — inside
+    const img2 = makeImage('img-2', 150, 150);
+
+    const allObjects: CanvasObject[] = [syntheticFrame, img1, img2];
+
+    const candidates = findAutoGroupCandidates(syntheticFrame, allObjects);
+
+    expect(candidates).toHaveLength(2);
+    expect(candidates.some((c) => c.id === 'img-1')).toBe(true);
+    expect(candidates.some((c) => c.id === 'img-2')).toBe(true);
+    // Both are ungrouped (no parentId)
+    expect(candidates.find((c) => c.id === 'img-1')?.oldParentId).toBeUndefined();
+    expect(candidates.find((c) => c.id === 'img-2')?.oldParentId).toBeUndefined();
+  });
+
+  it('should return no candidates when frame is drawn over empty area', () => {
+    // Synthetic frame drawn far from any objects: covers (600,600)→(800,800)
+    const syntheticFrame = makeSyntheticFrame(600, 600, 200, 200);
+
+    // Objects far away from the frame area
+    const img1 = makeImage('img-1', 50, 50);   // center (75,75)  — outside
+    const img2 = makeImage('img-2', 150, 150); // center (175,175) — outside
+
+    const allObjects: CanvasObject[] = [syntheticFrame, img1, img2];
+
+    const candidates = findAutoGroupCandidates(syntheticFrame, allObjects);
+
+    expect(candidates).toHaveLength(0);
+    expect(candidates).toEqual([]);
+  });
+
+  it('should update candidates as frame bounds change (simulating shrink)', () => {
+    // Three objects at (100,100), (200,200), (400,400), each 50x50
+    // Centers at (125,125), (225,225), (425,425)
+    const img1 = makeImage('img-1', 100, 100); // center (125,125)
+    const img2 = makeImage('img-2', 200, 200); // center (225,225)
+    const img3 = makeImage('img-3', 400, 400); // center (425,425)
+
+    // ── First call: large frame (0,0)→(500,500) → all 3 centers inside ──
+    const largeFrame = makeSyntheticFrame(0, 0, 500, 500);
+    const allObjectsLarge: CanvasObject[] = [largeFrame, img1, img2, img3];
+
+    const candidatesLarge = findAutoGroupCandidates(largeFrame, allObjectsLarge);
+    expect(candidatesLarge).toHaveLength(3);
+
+    // ── Second call: smaller frame (0,0)→(250,250) → third drops out ──
+    // Center (425,425) is outside (0,0)→(250,250); centers (125,125) and (225,225) remain inside
+    const smallFrame = makeSyntheticFrame(0, 0, 250, 250);
+    const allObjectsSmall: CanvasObject[] = [smallFrame, img1, img2, img3];
+
+    const candidatesSmall = findAutoGroupCandidates(smallFrame, allObjectsSmall);
+    expect(candidatesSmall).toHaveLength(2);
+    expect(candidatesSmall.some((c) => c.id === 'img-1')).toBe(true);
+    expect(candidatesSmall.some((c) => c.id === 'img-2')).toBe(true);
+    expect(candidatesSmall.some((c) => c.id === 'img-3')).toBe(false);
+  });
+
