+'use client';
+
+import { useState } from 'react';
+import {
+  Sheet,
+  SheetContent,
+  SheetHeader,
+  SheetTitle,
+} from '@/components/ui/sheet';
+import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
+import { Label } from '@/components/ui/label';
+import { FRAME_EXPORT_PRESETS } from '@/constants/frame-export-presets';
+
+interface FrameExportPanelProps {
+  open: boolean;
+  onOpenChange: (open: boolean) => void;
+  onExport: (
+    format: 'png' | 'jpg',
+    targetDimensions?: { width: number; height: number }
+  ) => Promise<void>;
+  defaultWidth?: number;
+  defaultHeight?: number;
+}
+
+export function FrameExportPanel({
+  open,
+  onOpenChange,
+  onExport,
+  defaultWidth,
+  defaultHeight,
+}: FrameExportPanelProps) {
+  const [format, setFormat] = useState<'png' | 'jpg'>('png');
+  const [customWidth, setCustomWidth] = useState<number>(Math.round(defaultWidth ?? 1080));
+  const [customHeight, setCustomHeight] = useState<number>(Math.round(defaultHeight ?? 1080));
+  const [aspectLocked, setAspectLocked] = useState(true);
+  const [scaleFactor, setScaleFactor] = useState<string>('1');
+
+  // Group presets by platform
+  const groupedPresets = FRAME_EXPORT_PRESETS.reduce(
+    (acc, preset) => {
+      if (!acc[preset.platform]) {
+        acc[preset.platform] = [];
+      }
+      acc[preset.platform].push(preset);
+      return acc;
+    },
+    {} as Record<string, typeof FRAME_EXPORT_PRESETS>
+  );
+
+  const handlePresetClick = (width: number, height: number) => {
+    onExport(format, { width, height });
+  };
+
+  const clamp = (v: number) => Math.max(1, Math.min(10000, isNaN(v) ? 1 : Math.round(v)));
+
+  const handleWidthChange = (newWidth: number) => {
+    const w = clamp(newWidth);
+    setCustomWidth(w);
+    if (aspectLocked && defaultWidth && defaultHeight) {
+      setCustomHeight(clamp(w * (defaultHeight / defaultWidth)));
+    }
+  };
+
+  const handleHeightChange = (newHeight: number) => {
+    const h = clamp(newHeight);
+    setCustomHeight(h);
+    if (aspectLocked && defaultWidth && defaultHeight) {
+      setCustomWidth(clamp(h * (defaultWidth / defaultHeight)));
+    }
+  };
+
+  const handleExportCustom = () => {
+    const finalWidth = clamp(customWidth * Number(scaleFactor));
+    const finalHeight = clamp(customHeight * Number(scaleFactor));
+    onExport(format, { width: finalWidth, height: finalHeight });
+  };
+
+  return (
+    <Sheet open={open} onOpenChange={onOpenChange}>
+      <SheetContent className="overflow-y-auto">
+        <SheetHeader>
+          <SheetTitle>Export Frame</SheetTitle>
+        </SheetHeader>
+
+        <div className="mt-6 space-y-6 pb-6">
+          {/* Quick Download */}
+          <div>
+            <h3 className="mb-3 text-sm font-medium">Quick Download</h3>
+            <div className="grid grid-cols-2 gap-2">
+              <button
+                onClick={() => onExport('png')}
+                className="rounded-md border border-input bg-background px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground"
+              >
+                PNG
+              </button>
+              <button
+                onClick={() => onExport('jpg')}
+                className="rounded-md border border-input bg-background px-4 py-2 text-sm font-medium hover:bg-accent hover:text-accent-foreground"
+              >
+                JPG
+              </button>
+            </div>
+          </div>
+
+          <div className="border-t" />
+
+          {/* Format Selector */}
+          <div>
+            <h3 className="mb-3 text-sm font-medium">Format</h3>
+            <RadioGroup
+              value={format}
+              onValueChange={(value) => setFormat(value as 'png' | 'jpg')}
+            >
+              <div className="flex items-center space-x-2">
+                <RadioGroupItem value="png" id="format-png" />
+                <Label htmlFor="format-png">PNG</Label>
+              </div>
+              <div className="flex items-center space-x-2">
+                <RadioGroupItem value="jpg" id="format-jpg" />
+                <Label htmlFor="format-jpg">JPG</Label>
+              </div>
+            </RadioGroup>
+          </div>
+
+          {/* Platform Presets */}
+          <div>
+            <h3 className="mb-3 text-sm font-medium">Presets</h3>
+            <div className="space-y-4">
+              {Object.entries(groupedPresets).map(([platform, presets]) => (
+                <div key={platform} data-platform={platform}>
+                  <h4 className="mb-2 text-xs font-semibold text-muted-foreground">
+                    {platform}
+                  </h4>
+                  <div className="grid gap-2">
+                    {presets.map((preset) => (
+                      <button
+                        key={preset.id}
+                        onClick={() =>
+                          handlePresetClick(preset.width, preset.height)
+                        }
+                        className="rounded-md border border-input bg-background px-4 py-2 text-sm hover:bg-accent hover:text-accent-foreground"
+                      >
+                        {preset.label}
+                      </button>
+                    ))}
+                  </div>
+                </div>
+              ))}
+            </div>
+          </div>
+
+          {/* Custom Dimensions */}
+          <div>
+            <h3 className="mb-3 text-sm font-medium">Custom Dimensions</h3>
+            <div className="space-y-4">
+              {/* Width and Height Inputs */}
+              <div className="grid grid-cols-2 gap-4">
+                <div>
+                  <Label htmlFor="custom-width">Width</Label>
+                  <input
+                    type="number"
+                    id="custom-width"
+                    value={customWidth}
+                    min={1}
+                    max={10000}
+                    onChange={(e) => handleWidthChange(Number(e.target.value))}
+                    className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
+                  />
+                </div>
+                <div>
+                  <Label htmlFor="custom-height">Height</Label>
+                  <input
+                    type="number"
+                    id="custom-height"
+                    value={customHeight}
+                    min={1}
+                    max={10000}
+                    onChange={(e) => handleHeightChange(Number(e.target.value))}
+                    className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
+                  />
+                </div>
+              </div>
+
+              {/* Aspect Lock Checkbox */}
+              <div className="flex items-center space-x-2">
+                <input
+                  type="checkbox"
+                  id="aspect-lock"
+                  checked={aspectLocked}
+                  onChange={(e) => setAspectLocked(e.target.checked)}
+                  className="h-4 w-4 rounded border-gray-300"
+                />
+                <Label htmlFor="aspect-lock">Lock aspect ratio</Label>
+              </div>
+
+              {/* Scale Factor */}
+              <div>
+                <h4 className="mb-2 text-sm font-medium">Scale Factor</h4>
+                <RadioGroup
+                  value={scaleFactor}
+                  onValueChange={setScaleFactor}
+                >
+                  {(['1', '2', '3'] as const).map((factor) => {
+                    const n = Number(factor);
+                    const w = clamp(customWidth * n);
+                    const h = clamp(customHeight * n);
+                    return (
+                      <div key={factor} className="flex items-center space-x-2">
+                        <RadioGroupItem value={factor} id={`scale-${factor}x`} />
+                        <Label htmlFor={`scale-${factor}x`}>
+                          {factor}x{' '}
+                          <span className="text-muted-foreground">
+                            ({w}×{h}px)
+                          </span>
+                        </Label>
+                      </div>
+                    );
+                  })}
+                </RadioGroup>
+              </div>
+
+              {/* Export Custom Button */}
+              <button
+                onClick={handleExportCustom}
+                className="w-full rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90"
+              >
+                Export Custom
+              </button>
+            </div>
+          </div>
+        </div>
+      </SheetContent>
+    </Sheet>
+  );
+}
