@@ -0,0 +1,64 @@
+import { describe, it, expect } from 'vitest';
+import {
+  FRAME_SIDE_ANCHORS,
+  FRAME_ALL_ANCHORS,
+  FRAME_CORNER_ANCHORS,
+} from '@/constants/frame';
+
+describe('Frame anchor constants', () => {
+  describe('FRAME_SIDE_ANCHORS', () => {
+    it('contains exactly 4 entries', () => {
+      expect(FRAME_SIDE_ANCHORS).toHaveLength(4);
+    });
+
+    it('contains top-center, middle-left, middle-right, bottom-center', () => {
+      expect(FRAME_SIDE_ANCHORS).toContain('top-center');
+      expect(FRAME_SIDE_ANCHORS).toContain('middle-left');
+      expect(FRAME_SIDE_ANCHORS).toContain('middle-right');
+      expect(FRAME_SIDE_ANCHORS).toContain('bottom-center');
+    });
+
+    it('does not contain corner anchor names', () => {
+      expect(FRAME_SIDE_ANCHORS).not.toContain('top-left');
+      expect(FRAME_SIDE_ANCHORS).not.toContain('top-right');
+      expect(FRAME_SIDE_ANCHORS).not.toContain('bottom-left');
+      expect(FRAME_SIDE_ANCHORS).not.toContain('bottom-right');
+    });
+  });
+
+  describe('FRAME_CORNER_ANCHORS', () => {
+    it('contains exactly 4 entries', () => {
+      expect(FRAME_CORNER_ANCHORS).toHaveLength(4);
+    });
+
+    it('contains top-left, top-right, bottom-left, bottom-right', () => {
+      expect(FRAME_CORNER_ANCHORS).toContain('top-left');
+      expect(FRAME_CORNER_ANCHORS).toContain('top-right');
+      expect(FRAME_CORNER_ANCHORS).toContain('bottom-left');
+      expect(FRAME_CORNER_ANCHORS).toContain('bottom-right');
+    });
+  });
+
+  describe('FRAME_ALL_ANCHORS', () => {
+    it('contains exactly 8 entries', () => {
+      expect(FRAME_ALL_ANCHORS).toHaveLength(8);
+    });
+
+    it('contains all corner anchor entries', () => {
+      for (const anchor of FRAME_CORNER_ANCHORS) {
+        expect(FRAME_ALL_ANCHORS).toContain(anchor);
+      }
+    });
+
+    it('contains all side anchor entries', () => {
+      for (const anchor of FRAME_SIDE_ANCHORS) {
+        expect(FRAME_ALL_ANCHORS).toContain(anchor);
+      }
+    });
+
+    it('has no duplicate entries', () => {
+      const unique = new Set(FRAME_ALL_ANCHORS);
+      expect(unique.size).toBe(FRAME_ALL_ANCHORS.length);
+    });
+  });
+});
