+import { describe, it, expect } from 'vitest';
+import { FRAME_AUTO_GROUP_BORDER_DASH } from '@/constants/frame';
+
+/**
+ * Pure-logic tests for the dash cleanup behavior in FrameNode.
+ *
+ * The actual cleanup lives in a useEffect inside FrameNode:
+ *   if (!isSelected && borderRef.current) {
+ *     borderRef.current.dash([]);
+ *     borderRef.current.getLayer()?.batchDraw();
+ *   }
+ *
+ * We extract the decision logic into a helper and test it here,
+ * following the same pattern as frame-stroke-override.test.ts.
+ */
+
+// Mirrors the cleanup logic in FrameNode's useEffect
+const shouldClearDash = (isSelected: boolean): boolean => !isSelected;
+
+// Mirrors the auto-group feedback logic in onTransform
+const getAutoGroupDash = (hasCandidates: boolean): number[] =>
+  hasCandidates ? FRAME_AUTO_GROUP_BORDER_DASH : [];
+
+describe('Frame dash cleanup on deselection', () => {
+  it('should clear dash when frame is not selected', () => {
+    expect(shouldClearDash(false)).toBe(true);
+  });
+
+  it('should not clear dash when frame is selected', () => {
+    expect(shouldClearDash(true)).toBe(false);
+  });
+
+  it('should set auto-group dash when candidates exist', () => {
+    expect(getAutoGroupDash(true)).toEqual(FRAME_AUTO_GROUP_BORDER_DASH);
+  });
+
+  it('should clear dash when no candidates exist', () => {
+    expect(getAutoGroupDash(false)).toEqual([]);
+  });
+
+  it('FRAME_AUTO_GROUP_BORDER_DASH should be a non-empty array', () => {
+    expect(FRAME_AUTO_GROUP_BORDER_DASH.length).toBeGreaterThan(0);
+  });
+
+  it('cleared dash should be an empty array (not undefined/null)', () => {
+    const clearedDash: number[] = [];
+    expect(clearedDash).toEqual([]);
+    expect(Array.isArray(clearedDash)).toBe(true);
+  });
+});
